const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const errors = [];

const allowedFields = new Set([
  'event_id',
  'customer_id',
  'company_name',
  'industry',
  'requirement',
  'purchase_window_days',
  'budget_range',
  'sales_owner',
  'report_date',
  'replay',
]);

if (body === null || typeof body !== 'object' || Array.isArray(body)) {
  return [{
    json: {
      input_valid: false,
      status: 'rejected',
      validation_errors: ['Request body must be a JSON object'],
    },
  }];
}

for (const field of Object.keys(body)) {
  if (!allowedFields.has(field)) {
    errors.push(`Field is not allowed: ${field}`);
  }
}

function requiredString(field, maxLength, pattern = null) {
  const value = body[field];
  if (typeof value !== 'string') {
    errors.push(`${field} must be a string`);
    return null;
  }
  const normalized = value.trim();
  if (normalized.length === 0) {
    errors.push(`${field} cannot be empty`);
    return null;
  }
  if (normalized.length > maxLength) {
    errors.push(`${field} exceeds ${maxLength} characters`);
  }
  if (pattern && !pattern.test(normalized)) {
    errors.push(`${field} contains unsupported characters`);
  }
  return normalized;
}

function optionalString(field, maxLength) {
  const value = body[field];
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== 'string') {
    errors.push(`${field} must be a string or null`);
    return null;
  }
  const normalized = value.trim();
  if (normalized.length === 0) {
    return null;
  }
  if (normalized.length > maxLength) {
    errors.push(`${field} exceeds ${maxLength} characters`);
  }
  return normalized;
}

const identifierPattern = /^[A-Za-z0-9._:-]+$/;
const eventId = requiredString('event_id', 128, identifierPattern);
const customerId = requiredString('customer_id', 128, identifierPattern);
const companyName = requiredString('company_name', 200);
const industry = optionalString('industry', 100);
const requirement = requiredString('requirement', 4000);
const budgetRange = optionalString('budget_range', 200);
const salesOwner = requiredString('sales_owner', 128, identifierPattern);

let purchaseWindowDays = body.purchase_window_days ?? null;
if (
  purchaseWindowDays !== null
  && (!Number.isInteger(purchaseWindowDays)
    || purchaseWindowDays < 0
    || purchaseWindowDays > 365)
) {
  errors.push('purchase_window_days must be an integer from 0 to 365 or null');
  purchaseWindowDays = null;
}

let replay = body.replay ?? false;
if (typeof replay !== 'boolean') {
  errors.push('replay must be a boolean');
  replay = false;
}

let reportDate = null;
if (typeof body.report_date !== 'string') {
  errors.push('report_date must use YYYY-MM-DD format');
} else {
  reportDate = body.report_date.trim();
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(reportDate);
  if (!match) {
    errors.push('report_date must use YYYY-MM-DD format');
  } else {
    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);
    const parsed = new Date(Date.UTC(year, month - 1, day));
    if (
      parsed.getUTCFullYear() !== year
      || parsed.getUTCMonth() !== month - 1
      || parsed.getUTCDate() !== day
    ) {
      errors.push('report_date must be a real date');
    }
  }
}

if (errors.length > 0) {
  return [{
    json: {
      input_valid: false,
      status: 'rejected',
      validation_errors: errors,
    },
  }];
}

return [{
  json: {
    input_valid: true,
    event_id: eventId,
    customer_id: customerId,
    company_name: companyName,
    industry,
    requirement,
    purchase_window_days: purchaseWindowDays,
    budget_range: budgetRange,
    sales_owner: salesOwner,
    report_date: reportDate,
    replay,
  },
}];

