const startResult = $input.first().json;
const incoming = $('Normalize Sales Lead').first().json;
const stored = startResult.input_data ?? incoming;

return [{
  json: {
    event_id: incoming.event_id,
    customer_id: stored.customer_id,
    company_name: stored.company_name,
    industry: stored.industry ?? null,
    requirement: stored.requirement,
    purchase_window_days: stored.purchase_window_days ?? null,
    budget_range: stored.budget_range ?? null,
    sales_owner: stored.sales_owner,
    report_date: incoming.report_date,
    workflow_run_id: startResult.run_id,
    workflow_run_status: startResult.status,
    should_process: startResult.should_process,
    duplicate: startResult.duplicate,
    replayed: startResult.replayed,
    retry_count: startResult.retry_count,
    duplicate_count: startResult.duplicate_count,
    processing_stage: startResult.processing_stage,
    resume_from: startResult.resume_from,
    checkpoint_data: startResult.checkpoint_data,
  },
}];

const chainResult = $input.first().json;
const context = $('Restore Workflow Context').first().json;

function invalid(reason) {
  throw new Error(`ai_output_validation: ${reason}`);
}

let analysis = chainResult.output;
if (typeof analysis === 'string') {
  try {
    analysis = JSON.parse(analysis);
  } catch (error) {
    invalid('result is not valid JSON');
  }
}

if (analysis === null || typeof analysis !== 'object' || Array.isArray(analysis)) {
  invalid('result is not a JSON object');
}

const allowedKeys = [
  'summary',
  'needs',
  'missing_information',
  'next_actions',
  'risk_flags',
];
const actualKeys = Object.keys(analysis).sort();
const expectedKeys = [...allowedKeys].sort();
if (
  actualKeys.length !== expectedKeys.length
  || actualKeys.some((key, index) => key !== expectedKeys[index])
) {
  invalid('result fields do not match the approved schema');
}

function requireText(value, name, maxLength) {
  if (typeof value !== 'string' || value.trim().length === 0) {
    invalid(`${name} must be a non-empty string`);
  }
  if (value.length > maxLength) {
    invalid(`${name} exceeds its maximum length`);
  }
  return value.trim();
}

function requireTextArray(value, name, minItems, maxItems, maxLength) {
  if (!Array.isArray(value)) {
    invalid(`${name} must be an array`);
  }
  if (value.length < minItems || value.length > maxItems) {
    invalid(`${name} has an invalid number of items`);
  }
  return value.map((item, index) =>
    requireText(item, `${name}[${index}]`, maxLength));
}

const riskValues = new Set([
  'product_capability_unverified',
  'pricing_or_discount',
  'delivery_commitment',
  'prompt_injection',
  'sensitive_information',
]);

const normalizedAnalysis = {
  summary: requireText(analysis.summary, 'summary', 500),
  needs: requireTextArray(analysis.needs, 'needs', 1, 5, 200),
  missing_information: requireTextArray(
    analysis.missing_information,
    'missing_information',
    0,
    5,
    200,
  ),
  next_actions: requireTextArray(
    analysis.next_actions,
    'next_actions',
    1,
    5,
    300,
  ),
  risk_flags: requireTextArray(analysis.risk_flags, 'risk_flags', 0, 5, 64),
};

if (normalizedAnalysis.risk_flags.some((value) => !riskValues.has(value))) {
  invalid('risk_flags contains an unsupported value');
}
if (new Set(normalizedAnalysis.risk_flags).size !== normalizedAnalysis.risk_flags.length) {
  invalid('risk_flags contains duplicate values');
}

if (context.purchase_window_days === null) {
  const hasMissingQuestion = normalizedAnalysis.missing_information
    .some((value) => /\u91c7\u8d2d|\u8bc4\u4f30\u65f6\u95f4|\u65f6\u95f4\u7a97\u53e3/.test(value));
  if (!hasMissingQuestion && normalizedAnalysis.missing_information.length < 5) {
    normalizedAnalysis.missing_information.push('\u91c7\u8d2d\u8bc4\u4f30\u65f6\u95f4');
  }

  const hasFollowupAction = normalizedAnalysis.next_actions
    .some((value) => /\u91c7\u8d2d|\u8bc4\u4f30\u65f6\u95f4|\u65f6\u95f4\u7a97\u53e3/.test(value));
  if (!hasFollowupAction && normalizedAnalysis.next_actions.length < 5) {
    normalizedAnalysis.next_actions.push('\u5411\u5ba2\u6237\u786e\u8ba4\u91c7\u8d2d\u8bc4\u4f30\u65f6\u95f4');
  }
}

const priority = context.purchase_window_days !== null
  && context.purchase_window_days <= 30
  ? 'high'
  : 'normal';

const reviewReasons = [...normalizedAnalysis.risk_flags];
const reviewStatus = reviewReasons.length > 0 ? 'pending' : 'not_required';

return [{
  json: {
    customer: {
      customer_id: context.customer_id,
      company_name: context.company_name,
      industry: context.industry,
      sales_owner: context.sales_owner,
    },
    run_id: context.workflow_run_id,
    event_id: context.event_id,
    requirement_snapshot: context.requirement,
    analysis: normalizedAnalysis,
    priority,
    review_status: reviewStatus,
    review_reasons: reviewReasons,
    notification_mode: 'preview',
    notification_channel: 'feishu',
  },
}];

