const input = $input.first().json;
const context = $('Restore Workflow Context').first().json;

// Read only error metadata. Never scan lead fields, model output, or raw bodies.
function collectError(value, depth = 0) {
  if (depth > 4 || value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value);
  if (typeof value !== 'object' || Array.isArray(value)) return '';
  return ['name', 'message', 'code', 'status', 'statusCode', 'httpCode', 'error', 'cause']
    .filter((key) => Object.prototype.hasOwnProperty.call(value, key))
    .map((key) => collectError(value[key], depth + 1))
    .join(' ');
}

const error = input.error;
const detail = collectError(error).toLowerCase();
const outputValidationFailure = [
  /ai[_ .-]?output[_ .-]?validation/,
  /output.?validation/,
  /output.?parser/,
  /structured.?output/,
  /model output (?:does not|doesn.t) fit required format/,
  /schema/,
  /failed to parse/,
  /could not parse/,
  /invalid json/,
  /invalid.+output/,
  /unexpected token/,
].some((pattern) => pattern.test(detail));

// Parser errors can quote invalid model text containing HTTP-like numbers.
// An explicit validation error must retain its review classification.
// Unrecognized or missing error metadata follows the existing failure branch.
return [{
  json: {
    run_id: context.workflow_run_id,
    event_id: context.event_id,
    customer_id: context.customer_id,
    failure_kind: outputValidationFailure ? 'output_validation' : 'service_unavailable',
    requires_human_review: outputValidationFailure,
    failure_stage: outputValidationFailure ? 'ai_output_validation' : 'ai_analysis',
    error_type: outputValidationFailure ? 'ai_output_invalid' : 'ai_service_unavailable',
    safe_message: outputValidationFailure
      ? 'AI output did not pass structural validation'
      : 'AI analysis service is unavailable',
  },
}];

