const context = $input.first().json;
const checkpoint = context.checkpoint_data;

if (checkpoint === null || typeof checkpoint !== 'object' || Array.isArray(checkpoint)) {
  throw new Error('Saved CRM checkpoint is unavailable');
}
if (checkpoint.run_id !== context.workflow_run_id) {
  throw new Error('Saved CRM checkpoint belongs to a different workflow run');
}

return [{ json: checkpoint }];
